import { cn } from "@/lib/utils"

/**
 * What state an object is in: a glyph and a word. All glyphs share one 10px box.
 * square = neutral (watching, investigating) · triangle = a problem · diamond = a chance to save · tick = done.
 * Only `issue` and `opportunity` use the signal colour. Never the glyph alone.
 */
type State = "watching" | "issue" | "opportunity" | "investigating" | "resolved"

const LABEL: Record<State, string> = { watching: "Watching", issue: "Issue", opportunity: "Opportunity", investigating: "Investigating", resolved: "Resolved" }

const TEXT: Record<State, string> = {
  watching: "text-muted-foreground",
  issue: "text-signal",
  opportunity: "text-foreground",
  investigating: "text-foreground",
  resolved: "text-muted-foreground",
}

function Glyph({ state }: { state: State }) {
  const common = "size-2.5 shrink-0"
  if (state === "issue") return <svg viewBox="0 0 10 10" aria-hidden="true" className={cn(common, "fill-current")}><path d="M5 1.2 9.4 8.8H.6z" /></svg>
  if (state === "opportunity") return <svg viewBox="0 0 10 10" aria-hidden="true" className={cn(common, "fill-signal")}><path d="M5 .8 9.2 5 5 9.2.8 5z" /></svg>
  if (state === "resolved") return <svg viewBox="0 0 10 10" aria-hidden="true" className={cn(common, "fill-none stroke-current stroke-[1.6]")}><path d="M1.5 5.2 4 7.5 8.5 2.5" /></svg>
  return (
    <svg viewBox="0 0 10 10" aria-hidden="true" className={cn(common, "fill-current", state === "investigating" && "animate-pulse motion-reduce:animate-none")}>
      <rect x="2" y="2" width="6" height="6" />
    </svg>
  )
}

export interface StateTagProps {
  state?: State
  /** Overrides the default word, e.g. "+14% power". */
  children?: React.ReactNode
  className?: string
}

export function StateTag({ state = "watching", children, className }: StateTagProps) {
  return (
    <span data-slot="state-tag" data-state={state} className={cn("inline-flex items-center gap-1.5 text-[13px] leading-[19px]", TEXT[state], className)}>
      <Glyph state={state} />
      {children ?? LABEL[state]}
    </span>
  )
}
